export type StandardLayoutOptions = {
  view: ActiveView;
  cardWidth: number;
  cardHeight: number;
  spouseGap: number;
  coupleGap: number;
  rowGap: number;
  childGap: number;
  padding: number;
};

/** PersonNodeCard — 배지·아바타·이름(2줄)·나이·전화 기준 (레이아웃·카드 공통) */
export const PERSON_NODE_METRICS = {
  padding: 12,
  headerHeight: 22,
  contentMarginTop: 8,
  avatarSize: 72,
  contentGap: 6,
  nameLineHeight: 19,
  nameLines: 2,
  ageLineHeight: 16,
  phoneLineHeight: 14,
  textGap: 2,
} as const;

export function computeStandardCardHeight(): number {
  const m = PERSON_NODE_METRICS;
  const textBlock =
    m.nameLineHeight * m.nameLines +
    m.ageLineHeight +
    m.phoneLineHeight +
    m.textGap * 2;
  return (
    m.padding * 2 +
    m.headerHeight +
    m.contentMarginTop +
    m.avatarSize +
    m.contentGap +
    textBlock
  );
}

/** 카드 그림자가 레이아웃 박스 아래로 번지는 정도 */
export const CARD_SHADOW_BLEED = 8;

export const STANDARD_LAYOUT_DEFAULTS: StandardLayoutOptions = {
  view: 'self',
  cardWidth: 158,
  cardHeight: computeStandardCardHeight(),
  spouseGap: 22,
  coupleGap: 56,
  rowGap: 256,
  childGap: 40,
  padding: 72,
};

